import{_ as n,C as i,o as t,c as s,E as o,a2 as r}from"./chunks/framework.Cm6XCzck.js";const k=JSON.parse('{"title":"Digital Employee Daily 002 — Control Plane and Work Runtime Are Different Systems","description":"","frontmatter":{"title":"Digital Employee Daily 002 — Control Plane and Work Runtime Are Different Systems","date":"2026-08-02","column":"digital-employee","category":"daily","summary":"Workday, ServiceNow, and Microsoft separate fleet governance from task execution, indicating that a Digital Employee platform needs both a control plane and a work runtime.","cover":"/assets/covers/control-plane-work-runtime-cover-v2.jpg","sources":["Workday Agent System of Record and Agent Gateway","ServiceNow AI Control Tower and Autonomous Workforce","Microsoft Agent 365"],"outline":"deep"},"headers":[],"relativePath":"en/digital-employee/2026-08-02-control-plane-work-runtime.md","filePath":"en/digital-employee/2026-08-02-control-plane-work-runtime.md","lastUpdated":1787407830000}'),l={name:"en/digital-employee/2026-08-02-control-plane-work-runtime.md"};function c(p,e,d,h,m,u){const a=i("ArticleCover");return t(),s("div",null,[o(a,{image:"/assets/covers/control-plane-work-runtime-cover-v2.jpg",kicker:"Digital Employee · Daily 002",title:"Control Plane and Work Runtime Are Different Systems",summary:"One system governs identity, ownership, and admission while another advances concrete work; they require separate models joined by a bounded contract.",version:"DD002",status:"Research Note · 2026-08-02",languageHref:"/zh/digital-employee/2026-08-02-control-plane-work-runtime",languageLabel:"简体中文"}),e[0]||(e[0]=r(`<h1 id="digital-employee-daily-002-—-control-plane-and-work-runtime-are-different-systems" tabindex="-1">Digital Employee Daily 002 — Control Plane and Work Runtime Are Different Systems <a class="header-anchor" href="#digital-employee-daily-002-—-control-plane-and-work-runtime-are-different-systems" aria-label="Permalink to &quot;Digital Employee Daily 002 — Control Plane and Work Runtime Are Different Systems&quot;">​</a></h1><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><p>Current enterprise products are converging on two distinct system responsibilities.</p><p>The first is a <strong>control plane</strong>: inventory, identity, ownership, policy, access, lifecycle, risk, cost, observability, and compliance across many Agents.</p><p>The second is a <strong>work runtime</strong>: accepting work, planning, executing workflow steps, invoking tools, maintaining state, escalating, recovering, producing evidence, and deciding whether work is complete.</p><p>Workday Agent System of Record, ServiceNow AI Control Tower, and Microsoft Agent 365 are strongest in the first layer. ServiceNow Autonomous Workforce and existing Agent runtimes expose parts of the second.</p><p>The research judgment is:</p><blockquote><p>A Digital Employee platform requires both layers, but they must remain separately modeled. Governance inventory cannot substitute for work execution, and an Agent runtime cannot substitute for organizational governance.</p></blockquote><h2 id="source" tabindex="-1">Source <a class="header-anchor" href="#source" aria-label="Permalink to &quot;Source&quot;">​</a></h2><h3 id="selected-official-material" tabindex="-1">Selected official material <a class="header-anchor" href="#selected-official-material" aria-label="Permalink to &quot;Selected official material&quot;">​</a></h3><ol><li><strong>Workday Agent System of Record and Agent Gateway</strong> — selected for its cross-provider registry, lifecycle, identity permissioning, interaction metering, analytics, cost, and accountability model.</li><li><strong>ServiceNow AI Control Tower</strong> — selected because it explicitly organizes governance into discovery, observation, governance, security, and measurement across Agents, models, workflows, identities, and MCP servers.</li><li><strong>ServiceNow Autonomous Workforce</strong> — selected because it connects AI Specialists to deterministic workflows, policies, traceability, human escalation, and end-to-end work execution.</li><li><strong>Microsoft Agent 365</strong> — selected for registry, Agent Map, lifecycle, owner, access governance, security, and compliance controls across first-party and external Agents.</li></ol><p>These sources show product architecture and vendor direction. They do not by themselves prove that one architecture is universally sufficient or economically appropriate for SMEs.</p><h2 id="observation" tabindex="-1">Observation <a class="header-anchor" href="#observation" aria-label="Permalink to &quot;Observation&quot;">​</a></h2><h3 id="_1-enterprise-governance-is-becoming-cross-provider" tabindex="-1">1. Enterprise governance is becoming cross-provider <a class="header-anchor" href="#_1-enterprise-governance-is-becoming-cross-provider" aria-label="Permalink to &quot;1. Enterprise governance is becoming cross-provider&quot;">​</a></h3><p>Workday states that first-party and third-party Agents can be registered and monitored through the Agent System of Record and Agent Gateway. Microsoft Agent Registry can synchronize external environments. ServiceNow AI Control Tower inventories first-party and third-party Agents, models, identities, workflows, and MCP servers.</p><p>The governance layer therefore sits above an individual Agent framework or model provider.</p><h3 id="_2-the-control-plane-manages-lifecycle-and-risk-not-individual-task-logic" tabindex="-1">2. The control plane manages lifecycle and risk, not individual task logic <a class="header-anchor" href="#_2-the-control-plane-manages-lifecycle-and-risk-not-individual-task-logic" aria-label="Permalink to &quot;2. The control plane manages lifecycle and risk, not individual task logic&quot;">​</a></h3><p>Across the three platforms, control-plane functions include:</p><ul><li>registration and discovery;</li><li>owner assignment;</li><li>identity and permissions;</li><li>activation, blocking, deactivation, and retirement;</li><li>policy and compliance;</li><li>runtime monitoring;</li><li>cost and value measurement;</li><li>inventory and relationship maps.</li></ul><p>These functions answer: <em>What is deployed, who owns it, what may it access, is it healthy, and should it remain active?</em></p><p>They do not fully answer: <em>How should this WorkOrder be decomposed, executed, recovered, verified, and closed?</em></p><h3 id="_3-work-execution-needs-deterministic-workflow-structure" tabindex="-1">3. Work execution needs deterministic workflow structure <a class="header-anchor" href="#_3-work-execution-needs-deterministic-workflow-structure" aria-label="Permalink to &quot;3. Work execution needs deterministic workflow structure&quot;">​</a></h3><p>ServiceNow explicitly contrasts probabilistic models with enterprise demand for deterministic outcomes. Its AI Specialists operate through established workflows, use organizational knowledge, follow policies, produce traceable actions, and escalate when human authority is needed.</p><p>This indicates that the execution layer needs more than an Agent identity. It needs state transitions, operation contracts, evidence, escalation, recovery, and completion gates.</p><h3 id="_4-observability-exists-at-two-levels" tabindex="-1">4. Observability exists at two levels <a class="header-anchor" href="#_4-observability-exists-at-two-levels" aria-label="Permalink to &quot;4. Observability exists at two levels&quot;">​</a></h3><p>The control plane observes fleet-level facts: inventory, security posture, performance, cost, and policy conformance.</p><p>The work runtime must observe work-level facts: current WorkOrder, active operation, session state, tool result, retry, checkpoint, evidence, review, and completion status.</p><p>Combining both into one undifferentiated log would make operational diagnosis and governance judgment harder.</p><h2 id="discussion" tabindex="-1">Discussion <a class="header-anchor" href="#discussion" aria-label="Permalink to &quot;Discussion&quot;">​</a></h2><h3 id="proposed-separation" tabindex="-1">Proposed separation <a class="header-anchor" href="#proposed-separation" aria-label="Permalink to &quot;Proposed separation&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Digital Employee Control Plane</span></span>
<span class="line"><span>  identity</span></span>
<span class="line"><span>  Position and owner</span></span>
<span class="line"><span>  registry</span></span>
<span class="line"><span>  authority and access policy</span></span>
<span class="line"><span>  provider and tool bindings</span></span>
<span class="line"><span>  lifecycle</span></span>
<span class="line"><span>  fleet health</span></span>
<span class="line"><span>  cost and evaluation</span></span>
<span class="line"><span>  compliance and audit views</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Digital Employee Work Runtime</span></span>
<span class="line"><span>  WorkOrder intake</span></span>
<span class="line"><span>  plan and workflow</span></span>
<span class="line"><span>  operation nodes</span></span>
<span class="line"><span>  sessions and tools</span></span>
<span class="line"><span>  checkpoint and retry</span></span>
<span class="line"><span>  escalation and recovery</span></span>
<span class="line"><span>  evidence production</span></span>
<span class="line"><span>  review and completion gates</span></span></code></pre></div><p>The control plane decides whether an execution identity is allowed and fit to operate. The work runtime decides how a specific unit of work progresses.</p><h3 id="why-one-layer-cannot-replace-the-other" tabindex="-1">Why one layer cannot replace the other <a class="header-anchor" href="#why-one-layer-cannot-replace-the-other" aria-label="Permalink to &quot;Why one layer cannot replace the other&quot;">​</a></h3><p>A registry without a runtime can list and govern Agents but cannot reliably complete organizational work.</p><p>A runtime without a control plane can execute tasks but cannot answer basic enterprise questions about ownership, lifecycle, sprawl, access, cost, policy, and retirement.</p><p>Therefore:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Governed Digital Employee Platform</span></span>
<span class="line"><span>= Control Plane</span></span>
<span class="line"><span>+ Work Runtime</span></span>
<span class="line"><span>+ explicit contract between them</span></span></code></pre></div><h3 id="the-contract-between-layers-matters-most" tabindex="-1">The contract between layers matters most <a class="header-anchor" href="#the-contract-between-layers-matters-most" aria-label="Permalink to &quot;The contract between layers matters most&quot;">​</a></h3><p>The control plane should issue a bounded execution context to the runtime:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">execution_context</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  digital_employee_id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  position_ref</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  work_order_ref</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  authority_snapshot_ref</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  allowed_tool_refs</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  provider_binding_ref</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  cost_policy_ref</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  evidence_policy_ref</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  escalation_policy_ref</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span></code></pre></div><p>The runtime should return structured facts:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">execution_result</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  lifecycle_events</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  tool_and_session_events</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  evidence_refs</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  cost_usage_ref</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  evaluation_ref</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  completion_judgment</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  unresolved_escalations</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span></code></pre></div><p>This allows governance to remain stable even when runtime implementations change.</p><h3 id="sme-first-implication" tabindex="-1">SME-first implication <a class="header-anchor" href="#sme-first-implication" aria-label="Permalink to &quot;SME-first implication&quot;">​</a></h3><p>Workday, ServiceNow, and Microsoft assume substantial enterprise infrastructure. CodeFlowMu should not reproduce a large control tower before proving one complete Digital Employee lifecycle.</p><p>The SME-first minimum should be:</p><ul><li>a small persistent registry;</li><li>explicit owner and Position;</li><li>tool/provider bindings;</li><li>lightweight policy checks;</li><li>runtime health and recovery view;</li><li>evidence and cost projection;</li><li>human authority for activation, exception, and release.</li></ul><h2 id="engineering-impact" tabindex="-1">Engineering Impact <a class="header-anchor" href="#engineering-impact" aria-label="Permalink to &quot;Engineering Impact&quot;">​</a></h2><h3 id="tmpa" tabindex="-1">TMPA <a class="header-anchor" href="#tmpa" aria-label="Permalink to &quot;TMPA&quot;">​</a></h3><p>No direct TMPA publication edit is made. This note supplies research input for separating governance records from operational execution while preserving references that allow later deterministic reconstruction.</p><h3 id="digital-employee" tabindex="-1">Digital Employee <a class="header-anchor" href="#digital-employee" aria-label="Permalink to &quot;Digital Employee&quot;">​</a></h3><p>The architecture should explicitly define Control Plane and Work Runtime as separate layers connected by stable contracts. Position and lifecycle belong primarily to the control plane; WorkOrder execution and evidence production belong primarily to the runtime.</p><h3 id="codeflowmu" tabindex="-1">CodeFlowMu <a class="header-anchor" href="#codeflowmu" aria-label="Permalink to &quot;CodeFlowMu&quot;">​</a></h3><p>CodeFlowMu already contains much of the Work Runtime layer:</p><ul><li>PM orchestration;</li><li>task and report lifecycle;</li><li>Session management;</li><li>skills and tools;</li><li>retry, HOLD, wake, and recovery mechanisms;</li><li>FCoP coordination;</li><li>evidence and completion gates.</li></ul><p>The next safe step is not to replace this runtime. It is to add a lightweight read-only Control Plane projection above it:</p><ol><li>register the current Open Dev Team as a Digital Employee;</li><li>register PM, DEV, QA, and OPS Position definitions;</li><li>expose provider, tool, Session, lifecycle, cost, and health bindings;</li><li>preserve existing runtime behavior during validation;</li><li>later make policy checks enforceable at WorkOrder admission and tool invocation boundaries.</li></ol><h2 id="future-work" tabindex="-1">Future Work <a class="header-anchor" href="#future-work" aria-label="Permalink to &quot;Future Work&quot;">​</a></h2><ol><li>Define the minimal Control Plane data model.</li><li>Map every current CodeFlowMu runtime fact to either Control Plane or Work Runtime.</li><li>Define the admission contract from Registry to WorkOrder.</li><li>Define which policy snapshot must be preserved for audit and replay.</li><li>Compare fleet-level observability with task-level observability.</li><li>Validate the two-layer model with a non-development Digital Employee use case.</li></ol><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ol><li>Workday, <strong>Agent System of Record</strong>: <a href="https://www.workday.com/en-us/artificial-intelligence/agent-system-of-record.html" target="_blank" rel="noreferrer">https://www.workday.com/en-us/artificial-intelligence/agent-system-of-record.html</a></li><li>Workday, <strong>The Workday Agent System of Record Is Now Generally Available</strong>: <a href="https://blog.workday.com/en-us/managing-ai-powered-future-of-work.html" target="_blank" rel="noreferrer">https://blog.workday.com/en-us/managing-ai-powered-future-of-work.html</a></li><li>Workday, <strong>CIO Buyer Guide to an AI-ready HR and Finance Platform</strong>: <a href="https://www.workday.com/en-us/topics/it/cio-buyers-guide.html" target="_blank" rel="noreferrer">https://www.workday.com/en-us/topics/it/cio-buyers-guide.html</a></li><li>ServiceNow, <strong>AI Control Tower</strong>: <a href="https://www.servicenow.com/products/ai-control-tower.html" target="_blank" rel="noreferrer">https://www.servicenow.com/products/ai-control-tower.html</a></li><li>ServiceNow, <strong>ServiceNow expands AI Control Tower</strong>: <a href="https://newsroom.servicenow.com/press-releases/details/2026/ServiceNow-expands-AI-Control-Tower-to-discover-observe-govern-secure-and-measure-AI-deployed-across-any-system-in-the-enterprise/default.aspx" target="_blank" rel="noreferrer">https://newsroom.servicenow.com/press-releases/details/2026/ServiceNow-expands-AI-Control-Tower-to-discover-observe-govern-secure-and-measure-AI-deployed-across-any-system-in-the-enterprise/default.aspx</a></li><li>ServiceNow, <strong>ServiceNow launches Autonomous Workforce that thinks and acts</strong>: <a href="https://newsroom.servicenow.com/press-releases/details/2026/ServiceNow-launches-Autonomous-Workforce-that-thinks-and-acts-adds-Moveworks-to-the-ServiceNow-AI-Platform/default.aspx" target="_blank" rel="noreferrer">https://newsroom.servicenow.com/press-releases/details/2026/ServiceNow-launches-Autonomous-Workforce-that-thinks-and-acts-adds-Moveworks-to-the-ServiceNow-AI-Platform/default.aspx</a></li><li>Microsoft, <strong>Microsoft Agent 365</strong>: <a href="https://www.microsoft.com/microsoft-agent-365" target="_blank" rel="noreferrer">https://www.microsoft.com/microsoft-agent-365</a></li><li>Microsoft Learn, <strong>Microsoft Agent 365 overview</strong>: <a href="https://learn.microsoft.com/en-us/microsoft-agent-365/overview" target="_blank" rel="noreferrer">https://learn.microsoft.com/en-us/microsoft-agent-365/overview</a></li><li>Microsoft Learn, <strong>Registry sync in the Microsoft 365 agent registry</strong>: <a href="https://learn.microsoft.com/en-us/microsoft-agent-365/admin/agent-registry" target="_blank" rel="noreferrer">https://learn.microsoft.com/en-us/microsoft-agent-365/admin/agent-registry</a></li><li>Microsoft Learn, <strong>Manage the agent lifecycle</strong>: <a href="https://learn.microsoft.com/en-us/agents/center-of-excellence/agent-lifecycle" target="_blank" rel="noreferrer">https://learn.microsoft.com/en-us/agents/center-of-excellence/agent-lifecycle</a></li></ol>`,61))])}const y=n(l,[["render",c]]);export{k as __pageData,y as default};
